{"data": {"id": "solana_6p6xgHyF7AeE6TZkSmFsko444wqoP15icUSqi2jfGiPN", "type": "token", "attributes": {"address": "6p6xgHyF7AeE6TZkSmFsko444wqoP15icUSqi2jfGiPN", "name": "OFFICIAL TRUMP", "symbol": "TRUMP", "decimals": 6, "image_url": "https://coin-images.coingecko.com/coins/images/53746/large/trump.png?1737171561", "image": {"thumb": "https://coin-images.coingecko.com/coins/images/53746/thumb/trump.png?1737171561", "small": "https://coin-images.coingecko.com/coins/images/53746/small/trump.png?1737171561", "large": "https://coin-images.coingecko.com/coins/images/53746/large/trump.png?1737171561"}, "banner_image_url": "https://assets.geckoterminal.com/5b820l844ctqrtm6o2irjg4b73jt", "coingecko_coin_id": "official-trump", "websites": ["https://gettrumpmemes.com"], "discord_url": null, "farcaster_url": null, "zora_url": null, "telegram_handle": null, "twitter_handle": "realDonaldTrump", "description": "TRUMP is a politics-themed digital coin built on the Solana blockchain that uses the brand of Donald Trump to foster a community-driven ecosystem. As a community-focused asset, it is designed to bridge political support with web ownership, operating within the PolitiFi sector to blend political movements with decentralized finance tools. The project's main value proposition lies in its official ties to Donald Trump’s media and business brands, which allows it to provide unique physical utility such as invitations to gala dinners and meetings at Mar-a-Lago.

The token serves as the primary currency for the officially licensed Trump Billionaires Club mobile and web game, where it is used for in-game purchases and unlocking features. By leveraging the Solana blockchain, the project ensures that these in-game actions and token transfers remain fast and cost-effective. The ecosystem remains stable through a programmatic release schedule that introduces new tokens slowly to prevent supply shocks, alongside the use of specialized market makers to maintain consistent liquidity for traders.

Holders can also participate in liquidity sharing by providing their tokens to automated systems to facilitate trading for others, often earning rewards or prizes in return. Beyond digital utility, holding a specific amount of the token is a requirement for attending exclusive real-world events, including VIP parties at Mar-a-Lago. The project is managed by the Trump Meme Team and is linked with Trump Media, with an investor base that includes a wide range of retail buyers and large holders who utilize secure custody services for their assets.", "gt_score": 87.01298701298701, "gt_score_details": {"pool": 85.714, "transaction": 100.0, "creation": 100.0, "info": 100.0, "holders": 81.25}, "gt_verified": true, "categories": ["Donald Trump", "Us Presidential Election 2024", "Charms Character"], "gt_category_ids": ["donald-trump", "us-presidential-election-2024", "charms-character"], "holders": {"count": 694584, "distribution_percentage": {"top_10": "88.3332", "11_20": "2.7431", "21_40": "2.7072", "rest": "6.2165"}, "last_updated": "2026-11-05T14:14:01Z"}, "mint_authority": "no", "freeze_authority": "no", "is_honeypot": "unknown", "is_nsfw": false, "developer_address": "GH7uSB9XoiqCNpAjn51LnRU1rNkvMarQxZoWNEs3EoDE", "developer_holding_percentage": "0.0"}}}
